index badge_episodes_open: CREATE INDEX badge_episodes_open ON badge_episodes(run,member,badge,closed_at)
index call_log_by_participant: CREATE INDEX call_log_by_participant ON call_log(participant,at)
index claims_by_participant: CREATE INDEX claims_by_participant ON claims(participant)
index lock_requests_by_participant: CREATE INDEX lock_requests_by_participant ON lock_requests(participant,asked_at)
index messages_channel: CREATE INDEX messages_channel ON messages(repo,run,seq)
index messages_repo: CREATE INDEX messages_repo ON messages(repo,seq)
index messages_run: CREATE INDEX messages_run ON messages(run,seq)
index token_readings_by_run: CREATE INDEX token_readings_by_run ON token_readings(run,t)
table badge_episodes: CREATE TABLE badge_episodes(run INTEGER NOT NULL,member TEXT NOT NULL,badge TEXT NOT NULL,pending_at INTEGER NOT NULL,opened_at INTEGER,closed_at INTEGER,clearing_at INTEGER)
table call_log: CREATE TABLE call_log(participant INTEGER NOT NULL,at TEXT NOT NULL,verb TEXT NOT NULL)
table changes: CREATE TABLE changes(repo TEXT PRIMARY KEY,version INTEGER NOT NULL)
table claims: CREATE TABLE claims(repo TEXT NOT NULL,path TEXT NOT NULL,participant INTEGER NOT NULL,kind TEXT NOT NULL DEFAULT 'inside',since_seq INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(repo,path,participant))
table deliveries: CREATE TABLE deliveries(participant INTEGER NOT NULL,seq INTEGER NOT NULL,at TEXT,PRIMARY KEY(participant,seq))
table flag_posts: CREATE TABLE flag_posts(repo TEXT NOT NULL,path TEXT NOT NULL,participant INTEGER NOT NULL,holder INTEGER NOT NULL,PRIMARY KEY(repo,path,participant,holder))
table liveness_warned: CREATE TABLE liveness_warned(run INTEGER NOT NULL,member TEXT NOT NULL,cond TEXT NOT NULL,PRIMARY KEY(run,member,cond))
table lock_requests: CREATE TABLE lock_requests(repo TEXT NOT NULL,participant INTEGER NOT NULL,asked_at TEXT NOT NULL,granted_at TEXT,merged_at TEXT,refused INTEGER NOT NULL DEFAULT 0)
table lock_waiters: CREATE TABLE lock_waiters(repo TEXT NOT NULL,participant INTEGER NOT NULL,PRIMARY KEY(repo,participant))
table member_activity: CREATE TABLE member_activity(run INTEGER NOT NULL,member TEXT NOT NULL,grew_at INTEGER,tokens INTEGER NOT NULL DEFAULT 0,context INTEGER,open_tool TEXT,open_target TEXT,open_since INTEGER,last_tool TEXT,finished INTEGER NOT NULL DEFAULT 0,at INTEGER NOT NULL,open_wait INTEGER NOT NULL DEFAULT 0,in_turn INTEGER,last_line TEXT,bg_target TEXT,bg_since INTEGER,bg_grew_at INTEGER,transcript TEXT,open_label TEXT,open_command TEXT,bg_label TEXT,bg_command TEXT,listener_running INTEGER,listener_ended_at INTEGER,context_at INTEGER,PRIMARY KEY(run,member))
table member_links: CREATE TABLE member_links(run INTEGER NOT NULL,member TEXT NOT NULL,connected INTEGER NOT NULL,lost_at INTEGER,seen_at INTEGER,cause TEXT,PRIMARY KEY(run,member))
table merge_locks: CREATE TABLE merge_locks(repo TEXT PRIMARY KEY,participant INTEGER NOT NULL,at TEXT NOT NULL,onto TEXT,reflog_mark INTEGER,files TEXT)
table messages: CREATE TABLE messages(seq INTEGER PRIMARY KEY AUTOINCREMENT,repo TEXT NOT NULL,author INTEGER NOT NULL,body TEXT NOT NULL,about TEXT,kind TEXT NOT NULL DEFAULT 'msg',mentions TEXT NOT NULL DEFAULT '[]',at TEXT NOT NULL,by_board INTEGER NOT NULL DEFAULT 0,meta TEXT,run INTEGER,endorses INTEGER,event TEXT,task INTEGER NOT NULL DEFAULT 0,after TEXT)
table participants: CREATE TABLE participants(id INTEGER PRIMARY KEY,run INTEGER NOT NULL,seat TEXT NOT NULL,place TEXT,doing TEXT NOT NULL DEFAULT '',files TEXT NOT NULL DEFAULT '[]',since_seq INTEGER NOT NULL DEFAULT 0,joined_at TEXT NOT NULL,ended_at TEXT,last_call TEXT,calls INTEGER NOT NULL DEFAULT 0,waiting INTEGER NOT NULL DEFAULT 0,listening INTEGER NOT NULL DEFAULT 0,nick TEXT,pack TEXT,verify INTEGER NOT NULL DEFAULT 0,pack_chosen INTEGER NOT NULL DEFAULT 0,wait_gen INTEGER NOT NULL DEFAULT 0,progress_at TEXT,board_call_at TEXT,quiet_flagged INTEGER NOT NULL DEFAULT 0,dropped_owing INTEGER,doing_at TEXT,doing_seq INTEGER,phase_shown TEXT,empty_waits INTEGER NOT NULL DEFAULT 0,idle_ended INTEGER NOT NULL DEFAULT 0,seated_at TEXT,merged INTEGER NOT NULL DEFAULT 0,UNIQUE(run,seat))
table phase_done: CREATE TABLE phase_done(run INTEGER NOT NULL,participant INTEGER NOT NULL,phase TEXT NOT NULL,at TEXT NOT NULL,PRIMARY KEY(run,participant,phase))
table runs: CREATE TABLE runs(id INTEGER PRIMARY KEY,repo TEXT NOT NULL,plan TEXT NOT NULL,title TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'open',opened_at TEXT NOT NULL,closed_at TEXT,link TEXT,kind TEXT NOT NULL DEFAULT 'plan',stale_flagged INTEGER NOT NULL DEFAULT 0,pruned_at TEXT,phase TEXT,phase_text TEXT,paused TEXT,resumed_at TEXT,stall_ms INTEGER NOT NULL DEFAULT 600000,protocol TEXT,authority TEXT,base TEXT,stall_posts INTEGER NOT NULL DEFAULT 0,paused_person INTEGER NOT NULL DEFAULT 0,phase_watch TEXT,phase_for TEXT,phase_at TEXT)
table seats: CREATE TABLE seats(run INTEGER NOT NULL,id TEXT NOT NULL,role TEXT,area TEXT,blockers TEXT NOT NULL DEFAULT '[]',state TEXT NOT NULL DEFAULT 'ready',ord INTEGER NOT NULL,link TEXT,PRIMARY KEY(run,id))
table server_facts: CREATE TABLE server_facts(name TEXT PRIMARY KEY,value INTEGER NOT NULL)
table settings: CREATE TABLE settings(name TEXT PRIMARY KEY,value TEXT NOT NULL)
table sqlite_sequence: CREATE TABLE sqlite_sequence(name,seq)
table token_readings: CREATE TABLE token_readings(run INTEGER NOT NULL,member TEXT NOT NULL,t TEXT NOT NULL,tokens INTEGER NOT NULL)
table transcripts: CREATE TABLE transcripts(run INTEGER NOT NULL,member TEXT NOT NULL,path TEXT NOT NULL,adapter TEXT,offset INTEGER NOT NULL DEFAULT 0,tokens INTEGER NOT NULL DEFAULT 0,readable INTEGER NOT NULL DEFAULT 0,read_at TEXT,moved_at TEXT,PRIMARY KEY(run,member))
user_version 2
